document.addEventListener("DOMContentLoaded",()=>{const apiKey="ffd7060b03ef1592a8c4811aba3ac52a";const city="Nairobi";const url=`https://api.openweathermap.org/data/2.5/weather?q=${city}&appid=${apiKey}&units=metric`;const weatherEl=document.getElementById("weather");fetch(url).then(response=>response.json()).then(data=>{if(data.cod===200){weatherEl.textContent=`${data.name}: ${data.main.temp}°C, ${data.weather[0].description}`}else{console.error("Error fetching the weather data:",data.message);weatherEl.textContent=""}}).catch(error=>{console.error("Error fetching the weather data:",error);weatherEl.textContent=""})});